int lengthOfLIS(const vector<int>& a) {
    // tails[k] = smallest tail of an increasing subsequence of length k+1
    vector<int> tails;
    for (int x : a) {
        auto it = lower_bound(tails.begin(), tails.end(), x);
        if (it == tails.end()) tails.push_back(x);
        else *it = x;
    }
    return (int)tails.size();
}

